//! Timed production seeks, coalescing and restoration. Paused-state support is reported separately.
use std::{path::PathBuf,time::{Duration,Instant}};
use serde_json::{json,Value};
use lyric_backend::runtime::Backend;
fn wait(b:&Backend,id:u64)->Value{let start=Instant::now();loop{let s=b.snapshot(u64::MAX);let c=&s["mediaCommand"];if c["id"]==id&&matches!(c["state"].as_str(),Some("confirmed"|"failed")){return json!({"command":c,"elapsedMs":start.elapsed().as_millis(),"playing":s["isPlaying"],"window":s["neteaseWindow"]})}if start.elapsed()>Duration::from_secs(6){return json!({"timeout":true,"command":c})}std::thread::sleep(Duration::from_millis(10));}}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let args:Vec<String>=std::env::args().collect();if args.get(1).map(String::as_str)!=Some("--authorized-and-restore"){return Err("authorization required".into())}let out=PathBuf::from(args.get(2).ok_or("output required")?);std::fs::create_dir_all(&out)?;
 let b=Backend::new(json!({"AllowedSources":["Netease"],"IgnoredSources":[],"OnlineSongInfo":false,"LyricSourceOrder":[]}),out.join("Data"),PathBuf::from(std::env::var_os("LOCALAPPDATA").unwrap()),out.join("Logs"));
 let start=Instant::now();let before=loop{let s=b.snapshot(u64::MAX);if s["canSeek"]==true&&s["rawSeconds"].is_number(){break s}if start.elapsed()>Duration::from_secs(8){b.close();return Err("no real seek channel".into())}std::thread::sleep(Duration::from_millis(10));};let connection_ms=start.elapsed().as_millis();
 let position=before["positionSeconds"].as_f64().unwrap();let duration=before["track"]["durationSeconds"].as_f64().unwrap();let song=before["track"]["songId"].clone();let playing=before["isPlaying"]==true;let started=Instant::now();let mut rows=vec![];
 for delta in [3.,-3.,6.,-5.,8.,-7.,4.,-4.,5.,-2.]{if b.snapshot(u64::MAX)["track"]["songId"]!=song{break}let r=match b.enqueue("seek",(position+delta).clamp(1.,duration-2.)){Ok(id)=>wait(&b,id),Err(e)=>json!({"error":e})};let ok=r["command"]["state"]=="confirmed";rows.push(r);if !ok{break}}
 let mut last=0;for delta in [9.,3.,-2.,7.,1.]{if let Ok(id)=b.enqueue("seek",(position+delta).clamp(1.,duration-2.)){last=id;}std::thread::sleep(Duration::from_millis(15));}let burst=wait(&b,last);
 let pause=b.command("pause",0.).unwrap_or(false);let paused=if pause{match b.enqueue("seek",(position+2.).clamp(1.,duration-2.)){Ok(id)=>wait(&b,id),Err(e)=>json!({"error":e})}}else{json!({"tested":false,"reason":"current client does not expose a usable SMTC pause session"})};
 let restored=if b.snapshot(u64::MAX)["track"]["songId"]==song{if pause{let _=b.command(if playing{"play"}else{"pause"},0.);}match b.enqueue("seek",(position+if playing{started.elapsed().as_secs_f64()}else{0.}).min(duration-1.)){Ok(id)=>wait(&b,id),Err(e)=>json!({"error":e})}}else{json!({"skipped":"track_changed"})};
 let attention=lyric_backend::netease_control::attention_diagnostics();b.close();let success=rows.len()==10&&rows.iter().all(|r|r["command"]["state"]=="confirmed")&&burst["command"]["state"]=="confirmed"&&restored["command"]["state"]=="confirmed";
 let report=json!({"success":success,"connectionMs":connection_ms,"sequentialSeeks":rows,"latestOfBurst":burst,"pausedSeek":paused,"restore":restored,"attention":attention,"scope":"current live NetEase client, production queue and real native readback; no promise for untested client versions"});std::fs::write(out.join("report.json"),serde_json::to_vec_pretty(&report)?)?;println!("{}",json!({"success":success,"connectionMs":connection_ms,"attention":attention,"pauseSupported":pause}));if !success{return Err("seek acceptance failed".into())}Ok(())
}
